firmware:
#include <OneWire.h>
#include <DallasTemperature.h>

const int ONE_WIRE_PIN = 15;
const int LED_PIN = 2;
const float READY_AT_C = 30.0;
OneWire oneWire(ONE_WIRE_PIN);
DallasTemperature sensors(&oneWire);
int last = -1;

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
  sensors.begin();
}

void loop() {
  sensors.requestTemperatures();
  float c = sensors.getTempCByIndex(0);
  if (c == DEVICE_DISCONNECTED_C) {
    delay(500);
    return;
  }
  int heating = c < READY_AT_C ? 1 : 0;
  if (heating != last) {
    digitalWrite(LED_PIN, heating ? HIGH : LOW);
    Serial.println(heating ? "HEATING" : "READY");
    last = heating;
  }
  delay(500);
}
